import { computed, mount, selector, signal } from 'kerfjs';
import { each } from 'kerfjs/list';
import { Combobox } from '@kerfjs/ui/combobox';
import { wireComboboxes } from '@kerfjs/ui/wire-comboboxes';

type Source = 'incoming' | 'outgoing';
type RecordData = { id: number; label: string };

function makeRow(record: RecordData) {
  return { id: record.id, label: signal(record.label) };
}

type Row = ReturnType<typeof makeRow>;
let nextPickerId = 0;

export function mountStudy(
  root: HTMLElement,
  onCommit: (value: string) => void,
  mark: (kind: 'row') => void,
) {
  const app = document.createElement('div');
  const inspector = document.createElement('section');
  const list = document.createElement('section');
  app.append(inspector, list);
  root.append(app);

  const counts = { incoming: signal(4), outgoing: signal(7) };
  const source = signal<Source>('incoming');
  const badge = computed(() => `${counts[source.value].value} crates`);
  const stopInspector = mount(inspector, () => (
    <div>
      <output data-badge="" title={badge}>{badge}</output>
      <input data-note="" aria-label="Note" />
    </div>
  ));

  const rows = signal([
    makeRow({ id: 1, label: 'One' }),
    makeRow({ id: 2, label: 'Two' }),
    makeRow({ id: 3, label: 'Three' }),
    makeRow({ id: 4, label: 'Four' }),
  ]);
  const selectedId = signal<number | null>(null);
  const isSelected = selector(selectedId);

  function renderRow(row: Row) {
    mark('row');
    const selected = isSelected(row.id);
    const ariaSelected = computed(() => selected.value ? 'true' : 'false');
    return (
      <div data-key={row.id} data-row={row.id} aria-selected={ariaSelected}>
        <span>{row.label}</span>
        <input aria-label={`Edit record ${row.id}`} />
      </div>
    );
  }

  const stopList = mount(list, () => each(rows.value, renderRow));

  function updateRows(update: () => void) {
    const editor = document.activeElement;
    if (!(editor instanceof HTMLInputElement) || !list.contains(editor)) {
      update();
      return;
    }

    const start = editor.selectionStart;
    const end = editor.selectionEnd;
    const direction = editor.selectionDirection;
    update();

    if (list.contains(editor)) {
      if (document.activeElement !== editor) editor.focus({ preventScroll: true });
      if (start !== null && end !== null && (
        editor.selectionStart !== start || editor.selectionEnd !== end ||
        editor.selectionDirection !== direction
      )) {
        editor.setSelectionRange(start, end, direction ?? 'none');
      }
    }
  }

  const pickerId = `study-fruit-${++nextPickerId}`;
  const suggestions = ['Apricot', 'Blueberry', 'Cherry'];
  let picker: { root: HTMLElement; stop: () => void } | undefined;
  let disposed = false;

  function open() {
    if (disposed || picker) return;
    const pickerRoot = document.createElement('div');
    app.append(pickerRoot);
    const stopField = mount(pickerRoot, () => (
      <Combobox id={pickerId} label="Fruit" suggestions={suggestions} createLabel={false} />
    ));
    const stopBehavior = wireComboboxes(pickerRoot, {
      onCommit: ({ value }) => {
        if (picker?.root === pickerRoot) onCommit(value);
      },
    });
    picker = {
      root: pickerRoot,
      stop() {
        stopBehavior();
        stopField();
        pickerRoot.remove();
      },
    };
  }

  function close() {
    const current = picker;
    picker = undefined;
    current?.stop();
  }

  return {
    count(source: Source, value: number) {
      counts[source].value = value;
    },
    mode(value: Source) {
      source.value = value;
    },
    select(id: number) {
      selectedId.value = id;
    },
    refetch(records: RecordData[]) {
      updateRows(() => {
        const byId = new Map(rows.value.map(row => [row.id, row] as const));
        rows.value = records.map(record => {
          const row = byId.get(record.id);
          if (!row) return makeRow(record);
          row.label.value = record.label;
          return row;
        });
      });
    },
    swap() {
      const [first, second, ...rest] = rows.value;
      if (!first || !second) return;
      updateRows(() => { rows.value = [second, first, ...rest]; });
    },
    open,
    close,
    dispose() {
      if (disposed) return;
      disposed = true;
      close();
      stopList();
      stopInspector();
      app.remove();
    },
  };
}
